const ledgerFlowTotals = `-- name: LedgerFlowTotals :many
SELECT le.currency::text AS currency,
       COALESCE(SUM(le.flow_amount) FILTER (WHERE le.type = 'INCOME'), 0)::bigint AS income,
       COALESCE(SUM(le.flow_amount) FILTER (WHERE le.type = 'EXPENSE'), 0)::bigint AS expense,
       COUNT(*)::int AS entries
FROM ledger_entries le
LEFT JOIN accounts a ON a.id = le.account_id
WHERE le.user_id = $1
  AND le.occurred_at IS NOT NULL
  AND le.type IN ('INCOME', 'EXPENSE')
  AND le.source NOT IN ('ADJUSTMENT', 'LOAN')
  AND (le.kind <> 'TRANSACTION' OR a.include_in_balance)
  AND ($2::timestamptz IS NULL OR le.occurred_at >= $2::timestamptz)
  AND ($3::timestamptz IS NULL OR le.occurred_at < $3::timestamptz)
  AND ($4::uuid IS NULL OR le.category_id = $4::uuid)
GROUP BY le.currency
`

type LedgerFlowTotalsParams struct {
	UserID     uuid.UUID          `json:"user_id"`
	FromAt     pgtype.Timestamptz `json:"from_at"`
	ToAt       pgtype.Timestamptz `json:"to_at"`
	CategoryID pgtype.UUID        `json:"category_id"`
}

type LedgerFlowTotalsRow struct {
	Currency string `json:"currency"`
	Income   int64  `json:"income"`
	Expense  int64  `json:"expense"`
	Entries  int32  `json:"entries"`
}

// Income/expense flows within [from_at, to_at) per currency. Transactions on accounts
// excluded from the balance are left out; group shares always count. Balance
// adjustments (starting balances, corrections) and loan bookings are not income or expense.
func (q *Queries) LedgerFlowTotals(ctx context.Context, arg LedgerFlowTotalsParams) ([]LedgerFlowTotalsRow, error) {
	rows, err := q.db.Query(ctx, ledgerFlowTotals,
		arg.UserID,
		arg.FromAt,
		arg.ToAt,
		arg.CategoryID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LedgerFlowTotalsRow
	for rows.Next() {
		var i LedgerFlowTotalsRow
		if err := rows.Scan(
			&i.Currency,
			&i.Income,
			&i.Expense,
			&i.Entries,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

